package org.apache.commons.collections4.trie.analyzer;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/**
 * Tests {@link StringKeyAnalyzer}.
 */
public class StringKeyAnalyzerTest {

    /**
     * Tests that isPrefix correctly extracts the prefix substring when
     * offsetInBits is non-zero. The prefix substring should start at
     * offsetInBits/LENGTH and end at (offsetInBits+lengthInBits)/LENGTH.
     */
    @Test
    public void testIsPrefixWithNonZeroOffset() {
        // LENGTH = Character.SIZE = 16 bits
        // prefix = "abcdef", offsetInBits = 16, lengthInBits = 32
        // offsetInBits / LENGTH = 1 (start index)
        // (offsetInBits + lengthInBits) / LENGTH = (16+32)/16 = 3 (correct end index)
        // lengthInBits / LENGTH = 2 (buggy end index)
        // Correct: substring(1, 3) = "bc"
        // Buggy:   substring(1, 2) = "b"
        String prefix = "abcdef";
        int offsetInBits = 16;
        int lengthInBits = 32;

        // key starts with "b" but not with "bc"
        String key = "bxyz";

        // Correct behavior: prefix substring is "bc", key does NOT start with "bc"
        boolean result = StringKeyAnalyzer.INSTANCE.isPrefix(prefix, offsetInBits, lengthInBits, key);
        assertFalse(result, "isPrefix should return false when the extracted prefix is 'bc' and key is 'bxyz'");
    }

    /**
     * Tests that isPrefix correctly returns true when the key matches
     * the extracted prefix at a non-zero offset.
     */
    @Test
    public void testIsPrefixWithNonZeroOffsetMatching() {
        String prefix = "abcdef";
        int offsetInBits = 16;
        int lengthInBits = 32;

        // Correct prefix extracted is "bc"
        String key = "bcxyz";

        boolean result = StringKeyAnalyzer.INSTANCE.isPrefix(prefix, offsetInBits, lengthInBits, key);
        assertTrue(result, "isPrefix should return true when the extracted prefix is 'bc' and key is 'bcxyz'");
    }

    /**
     * Tests isPrefix with zero offset (should work correctly in both versions).
     */
    @Test
    public void testIsPrefixWithZeroOffset() {
        String prefix = "abcdef";
        int offsetInBits = 0;
        int lengthInBits = 32;

        String key = "abcxyz";

        boolean result = StringKeyAnalyzer.INSTANCE.isPrefix(prefix, offsetInBits, lengthInBits, key);
        assertTrue(result, "isPrefix should return true with zero offset");
    }
}

