@Test
    @SuppressWarnings("unchecked")
    void testRemoveWithNullElementInjected() throws Exception {
        // add() rejects nulls, so we use reflection to inject a null into the internal array
        // to test that remove() still advances the start pointer when it encounters null.
        final CircularFifoQueue<String> fifo = new CircularFifoQueue<>(5);
        fifo.add("A");
        fifo.add("B");

        // Use reflection to set elements[start] to null (simulating e.g. deserialized state)
        final java.lang.reflect.Field elementsField = CircularFifoQueue.class.getDeclaredField("elements");
        elementsField.setAccessible(true);
        final Object[] elements = (Object[]) elementsField.get(fifo);
        elements[0] = null; // start is 0, so this is the head element

        // remove() should return the null and advance past it
        final String removed = fifo.remove();
        assertEquals(null, removed, "remove() should return the null element");
        assertEquals(1, fifo.size(), "size should decrease after remove()");

        // The next remove() should return "B", not get stuck returning null again
        final String next = fifo.remove();
        assertEquals("B", next, "remove() should advance past the null element");
        assertEquals(0, fifo.size(), "queue should be empty after removing both elements");
    }

