    @Test
    @SuppressWarnings("unchecked")
    void testBagAddZeroCopiesNoModCountIncrement() {
        if (!isAddSupported()) {
            return;
        }

        final Bag<T> bag = makeObject();
        bag.add((T) "A");
        bag.add((T) "A");
        bag.add((T) "B");

        final Iterator<T> it = bag.iterator();
        it.next(); // consume first element

        // Adding 0 copies should not modify the bag and should not increment modCount.
        // The iterator should continue to work without throwing CME.
        bag.add((T) "C", 0);

        // This should NOT throw ConcurrentModificationException because no actual
        // modification occurred (0 copies were added).
        it.next();
