package org.apache.commons.collections4.bloomfilter;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.function.BiPredicate;

import org.apache.commons.lang3.tuple.Pair;
import org.junit.jupiter.api.Test;

class CountingPredicateTest {

    private final Integer[] ary = {Integer.valueOf(1), Integer.valueOf(2)};

    private BiPredicate<Integer, Integer> makeFunc(final BiPredicate<Integer, Integer> inner, final List<Pair<Integer, Integer>> result) {
        return (x, y) -> {
            if (inner.test(x, y)) {
                result.add(Pair.of(x, y));
                return true;
            }
            return false;
        };
    }

    /**
     * Test when the predicate array is longer than other array as determined by the number
     * of times cp.test() is called and all other values result in a true statement.
     */
    @Test
    void testPredicateLonger() {
        final List<Pair<Integer, Integer>> expected = new ArrayList<>();
        final List<Pair<Integer, Integer>> result = new ArrayList<>();
        expected.add(Pair.of(1, 3));

        CountingPredicate<Integer> cp = new CountingPredicate<>(ary, makeFunc((x, y) -> x != null, result));
        assertTrue(cp.test(Integer.valueOf(3)));
        assertEquals(expected, result);
        expected.add(Pair.of(2, null));
        assertTrue(cp.processRemaining());
        assertEquals(expected, result);

        // if the other array is zero length then cp.test() will not be called so
        // we can just call cp.processRemaining() here.
        expected.clear();
        expected.add(Pair.of(1, null));
        expected.add(Pair.of(2, null));
        result.clear();
        cp = new CountingPredicate<>(ary, makeFunc((x, y) -> x != null, result));
        assertTrue(cp.processRemaining());
        assertEquals(expected, result);

        // If a test fails then the result should be false and the rest of the list should
        // not be processed.
        expected.clear();
        expected.add(Pair.of(1, null));
        result.clear();
        cp = new CountingPredicate<>(ary, makeFunc((x, y) -> x == Integer.valueOf(1), result));
        assertFalse(cp.processRemaining());
        assertEquals(expected, result);
    }

    /**
     * Test when the predicate array is shorter than other array as determined by the number
     * of times cp.test() is called and all other values result in a true statement.
     */
    @Test
    void testPredicateSameLength() {
        final List<Pair<Integer, Integer>> expected = new ArrayList<>();
        final List<Pair<Integer, Integer>> result = new ArrayList<>();
        expected.add(Pair.of(1, 3));
        expected.add(Pair.of(2, 3));
        final CountingPredicate<Integer> cp = new CountingPredicate<>(ary, makeFunc((x, y) -> true, result));
        assertTrue(cp.test(3));
        assertTrue(cp.test(3));
        assertEquals(expected, result);
        assertTrue(cp.processRemaining());
        assertEquals(expected, result);
    }

    /**
     * Test when the predicate array is shorter than other array as determined by the number
     * of times cp.test() is called and all other values result in a true statement.
     */
    @Test
    void testPredicateShorter() {
        final List<Pair<Integer, Integer>> expected = new ArrayList<>();
        final List<Pair<Integer, Integer>> result = new ArrayList<>();
        final Integer[] shortAry = {Integer.valueOf(3)};
        expected.add(Pair.of(3, 1));
        expected.add(Pair.of(null, 2));
        final CountingPredicate<Integer> cp = new CountingPredicate<>(shortAry, makeFunc((x, y) -> true, result));
        for (final Integer i : ary) {
            assertTrue(cp.test(i));
        }
        assertEquals(expected, result);
        assertTrue(cp.processRemaining());
        assertEquals(expected, result);
    }

    /**
     * Test that processRemaining() updates idx so repeated calls do not re-process elements.
     * After processRemaining() exhausts the array, idx should be at the limit,
     * so a second call should not invoke func again.
     */
    @Test
    void testProcessRemainingDoesNotReProcess() {
        final Integer[] testAry = {Integer.valueOf(1), Integer.valueOf(2)};
        // Atomic counter to count how many times func.test() is called.
        java.util.concurrent.atomic.AtomicInteger callCount = new java.util.concurrent.atomic.AtomicInteger(0);
        final BiPredicate<Integer, Integer> countingFunc = (x, y) -> {
            callCount.incrementAndGet();
            return true;
        };
        final CountingPredicate<Integer> cp = new CountingPredicate<>(testAry, countingFunc);

        // First processRemaining() should process both elements (2 calls).
        assertTrue(cp.processRemaining());
        assertEquals(2, callCount.get());

        // Second processRemaining() should NOT re-process any elements (still 2 calls).
        assertTrue(cp.processRemaining());
        assertEquals(2, callCount.get());
    }

    /**
     * Test that test() calls after processRemaining() use the updated idx.
     * After processRemaining() exhausts the array, idx should be at the limit,
     * so subsequent test() calls should pass null as the first argument.
     */
    @Test
    void testAfterProcessRemainingUsesUpdatedIdx() {
        final Integer[] testAry = {Integer.valueOf(1), Integer.valueOf(2)};
        final List<Pair<Integer, Integer>> result = new ArrayList<>();
        final BiPredicate<Integer, Integer> func = makeFunc((x, y) -> true, result);
        final CountingPredicate<Integer> cp = new CountingPredicate<>(testAry, func);

        // processRemaining() processes all remaining elements with second arg null.
        assertTrue(cp.processRemaining());
        assertEquals(2, result.size());
        assertEquals(Pair.of(1, null), result.get(0));
        assertEquals(Pair.of(2, null), result.get(1));

        // After processRemaining(), test() should pass null as first arg (idx exhausted).
        assertTrue(cp.test(Integer.valueOf(99)));
        assertEquals(3, result.size());
        assertEquals(Pair.of(null, Integer.valueOf(99)), result.get(2));
    }
}

